mapper.update:
UPDATE ai_assistant_privacy_operation SET control_acceptance_audit_id = #{auditId}, operation_fingerprint = #{fingerprint}
WHERE organization_id = #{organizationId} AND operation_key = #{operationKey}
  AND reason = 'dsr' AND control_acceptance_audit_id IS NULL

UPDATE ai_assistant_privacy_operation_workspace SET state = 'verified', placement_catalog = #{catalog,jdbcType=VARCHAR},
  verified_work_revision = #{revision}, verified_at = CURRENT_TIMESTAMP(6)
WHERE organization_id = #{organizationId} AND operation_key = #{operationKey} AND workspace_id = #{workspaceId}

mapper.select:
SELECT DISTINCT o.organization_id FROM ai_assistant_privacy_operation o
WHERE o.organization_id > #{afterId}
  AND (o.completed_at IS NULL OR EXISTS (
    SELECT 1 FROM ai_assistant_privacy_operation_workspace w
    WHERE w.organization_id = o.organization_id AND w.operation_key = o.operation_key AND w.state <> 'verified'))
ORDER BY o.organization_id LIMIT #{limit}

SELECT COUNT(*) FROM ai_assistant_privacy_operation o WHERE o.organization_id = #{organizationId}
  AND (o.completed_at IS NULL OR EXISTS (SELECT 1 FROM ai_assistant_privacy_operation_workspace w
    WHERE w.organization_id = o.organization_id AND w.operation_key = o.operation_key AND w.state <> 'verified'))
